import re

def parse(lines):
    hdr = re.compile(r'^\s+T(?:\s+\d+\+?)+\s*$')
    row = re.compile(r'^\s*(\S+)((?:\s+\d+)+)\s*$')
    blocks = []
    skip = []
    labels = None
    table = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if l.lstrip().startswith('$ '):
            skip.append(i)
            continue
        if hdr.match(l):
            labels = l.split()
            table = {'name': 'queue_shape', 'kind': 'table', 'lines': [i], 'records': []}
            blocks.append(table)
            continue
        m = row.match(l)
        if m and labels:
            vals = m.group(2).split()
            if len(vals) != len(labels):
                continue
            rec = {}
            for k in range(len(labels)):
                rec[labels[k]] = int(vals[k])
            if m.group(1) == 'TOTAL':
                blocks.append({'name': 'totals', 'kind': 'kv', 'lines': [i], 'records': [rec]})
            else:
                r = {'domain': m.group(1)}
                r.update(rec)
                table['lines'].append(i)
                table['records'].append(r)
    return {'blocks': blocks, 'skip': skip}
